 private function productList(Request $r,?Product $editing){$base=Product::query();$stats=['Total'=>(clone $base)->count(),'Active'=>(clone $base)->where('active',true)->count(),'Automatic'=>(clone $base)->where('auto_approve',true)->count(),'Manual'=>(clone $base)->where('auto_approve',false)->count()];$q=Product::query();if($r->filled('q'))$q->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhere('code','like','%'.$r->q.'%'));if($r->filled('status'))$q->where('active',$r->status==='active');return view('products',['products'=>$q->latest()->paginate(20)->withQueryString(),'editing'=>$editing,'stats'=>$stats]);}
