  $locations=json_decode(file_get_contents(resource_path('data/tanzania_locations.json')),true);$region=(string)$r->input('region');$district=(string)$r->input('district');
  $v=$r->validate(['customer_id'=>'nullable|integer|exists:users,id','name'=>'required|string|max:150','email'=>'nullable|email|max:200','phone'=>'required|string|max:30','alternative_phone'=>'nullable|string|max:30','id_number'=>'required|string|max:80','date_of_birth'=>'required|date|before:today','gender'=>'required|in:male,female','region'=>['required',Rule::in(array_keys($locations))],'district'=>['required',Rule::in(array_keys($locations[$region]??[]))],'ward'=>['required',Rule::in($locations[$region][$district]??[])],'address'=>'required|string|max:1000','occupation'=>'required|string|max:150','next_of_kin'=>'required|string|max:150','next_of_kin_phone'=>'required|string|max:30','product_id'=>'required|exists:products,id','utility_type'=>'nullable|in:electricity,water','device_price'=>'required|integer|min:1|max:1000000000','meter_number'=>'required|string|max:80','meter_brand_model'=>'nullable|string|max:150','device_serial'=>'nullable|string|max:100','installation_address'=>'required|string|max:1000','installation_date'=>'nullable|date','quotation_attached'=>'accepted','accepted'=>'accepted','upfront_amount'=>'required|integer|min:0|max:1000000000','upfront_reference'=>['required','string','max:150','unique:application_upfront_payments,reference','unique:payments,reference'],'upfront_channel'=>'required|in:bank,mobile_money,cash','upfront_paid_at'=>'required|date|before_or_equal:today','upfront_evidence'=>'required|string|max:1000']);
  $product=Product::whereKey($v['product_id'])->whereIn('category',['submeter','token'])->where('active',true)->firstOrFail();$financier=$product->financiers()->where('active',true)->inRandomOrder()->first();if(!$financier)throw ValidationException::withMessages(['product_id'=>'No active financier is available for this product.']);$terms=$product->quote();if($product->category==='token'){$terms['value']=(int)$v['device_price'];$terms['principal']=$terms['value']-$terms['down_payment']+($terms['commission_financed']?$terms['commission']:0);$terms['repayment_total']=$terms['principal']+$terms['finance_charge'];}if((int)$v['upfront_amount']!==(int)$terms['upfront'])throw ValidationException::withMessages(['upfront_amount'=>'The upfront payment must equal '.number_format($terms['upfront']).' TZS.']);
  $customer=($v['customer_id']??null)?User::where('role','customer')->findOrFail($v['customer_id']):(!empty($v['email'])?User::where('role','customer')->where('email',$v['email'])->first():null);if($customer&&$r->user()->role==='supplier'&&$customer->onboarded_by!==$r->user()->id)throw ValidationException::withMessages(['email'=>'This customer is managed by another supplier.']);$emailTaken=!empty($v['email'])&&User::where('email',$v['email'])->when($customer,fn($q)=>$q->whereKeyNot($customer->id))->exists();if($emailTaken)throw ValidationException::withMessages(['email'=>'This email is already used by another account.']);if(User::where('phone',$v['phone'])->when($customer,fn($q)=>$q->whereKeyNot($customer->id))->exists())throw ValidationException::withMessages(['phone'=>'This phone number is already assigned to another customer.']);if(User::where('id_number',$v['id_number'])->when($customer,fn($q)=>$q->whereKeyNot($customer->id))->exists())throw ValidationException::withMessages(['id_number'=>'This identification number is already assigned to another customer.']);
