  $application->customer->update(['first_name'=>$r->input('first_name')?:Str::before($application->customer->name,' '),'middle_name'=>$r->input('middle_name'),'last_name'=>$r->input('last_name')?:Str::afterLast($application->customer->name,' '),'id_type'=>$r->input('id_type'),'id_number'=>$v['id_number']]);$application->update(['id_type'=>$r->input('id_type'),'meter_number'=>$v['meter_number']]);if($product->auto_approve)$service->approve($application,$r->user(),true);$message=$product->auto_approve?'Customer application auto-approved.'.((int)$terms['upfront']>0?' Upfront payment was verified automatically.':' No upfront payment is required.'):'Customer application submitted for manual approval.';return redirect('/applications')->with('success',$message);
