 public function audit(Request $r){$base=AuditLog::query();$stats=['Total'=>(clone $base)->count(),'Today'=>(clone $base)->whereDate('created_at',today())->count(),'Users'=>(clone $base)->distinct('user_id')->count('user_id')];$q=AuditLog::latest();if($r->filled('q'))$q->where(fn($x)=>$x->where('action','like','%'.$r->q.'%')->orWhere('entity','like','%'.$r->q.'%'));return view('audit',['logs'=>$q->paginate(30)->withQueryString(),'stats'=>$stats]);}
 public function editApplication(Request $r,LoanApplication $application){Visibility::check($application,$r->user());abort_unless($application->status==='submitted',403);$application->load('customer','product');$locations=json_decode(file_get_contents(resource_path('data/tanzania_locations.json')),true);return view('application-edit',compact('application','locations'));}
 public function updateApplication(Request $r,LoanApplication $application){Visibility::check($application,$r->user());abort_unless($application->status==='submitted',403);$locations=json_decode(file_get_contents(resource_path('data/tanzania_locations.json')),true);$region=(string)$r->input('region');$district=(string)$r->input('district');$v=$r->validate(['name'=>'required|string|max:150','email'=>['required','email','max:200',Rule::unique('users')->ignore($application->user_id)],'phone'=>'required|string|max:30','alternative_phone'=>'nullable|string|max:30','id_number'=>'required|string|max:80','date_of_birth'=>'required|date|before:today','gender'=>'required|in:male,female','region'=>['required',Rule::in(array_keys($locations))],'district'=>['required',Rule::in(array_keys($locations[$region]??[]))],'ward'=>['required',Rule::in($locations[$region][$district]??[])],'customer_address'=>'required|string|max:1000','occupation'=>'required|string|max:150','next_of_kin'=>'required|string|max:150','next_of_kin_phone'=>'required|string|max:30','utility_type'=>'required|in:electricity,water','device_price'=>'required|integer|min:1|max:1000000000','meter_brand_model'=>'required|string|max:150','device_serial'=>'nullable|string|max:100','installation_address'=>'required|string|max:1000','installation_date'=>'nullable|date','quotation_attached'=>'accepted']);DB::transaction(function()use($r,$application,$v){$locked=LoanApplication::lockForUpdate()->findOrFail($application->id);if($locked->status!=='submitted')throw ValidationException::withMessages(['application'=>'This application has already been reviewed and can no longer be edited.']);$locked->customer()->update(['name'=>$v['name'],'email'=>$v['email'],'phone'=>$v['phone'],'alternative_phone'=>$v['alternative_phone']??null,'date_of_birth'=>$v['date_of_birth'],'gender'=>$v['gender'],'region'=>$v['region'],'district'=>$v['district'],'ward'=>$v['ward'],'address'=>$v['customer_address'],'occupation'=>$v['occupation'],'next_of_kin'=>$v['next_of_kin'],'next_of_kin_phone'=>$v['next_of_kin_phone']]);$locked->update(['phone'=>$v['phone'],'id_number'=>$v['id_number'],'address'=>$v['installation_address'],'utility_type'=>$v['utility_type'],'device_price'=>$v['device_price'],'meter_brand_model'=>$v['meter_brand_model'],'device_serial'=>$v['device_serial']??null,'installation_date'=>$v['installation_date']??null,'quotation_attached'=>true]);$this->logAudit($r,'application.updated',$locked);});return redirect('/applications/'.$application->id)->with('success','Application details updated.');}
 public function payouts(Request $r){$scope=fn($q)=>$r->user()->role==='supplier'?$q->whereHas('loan.customer',fn($customer)=>$customer->where('onboarded_by',$r->user()->id)):$q;$base=$scope(Payout::query());$stats=['Total payouts'=>(clone $base)->count(),'Pending'=>(clone $base)->where('status','pending')->count(),'Paid'=>(clone $base)->where('status','paid')->count(),'Pending amount'=>(clone $base)->where('status','pending')->sum('amount')];$q=$scope(Payout::with('loan.customer','loan.application','batch'));if($r->filled('status'))$q->where('status',$r->status);if($r->filled('q'))$q->whereHas('loan',fn($x)=>$x->where('reference','like','%'.$r->q.'%')->orWhereHas('customer',fn($c)=>$c->where('name','like','%'.$r->q.'%')));$payouts=$q->latest()->paginate(20)->withQueryString();return view('payouts',compact('payouts','stats'));}
 public function bookPayouts(Request $r){$v=$r->validate(['payout_ids'=>'required|array|min:1','payout_ids.*'=>'integer|distinct|exists:payouts,id','payment_reference'=>'required|string|max:150|unique:disbursement_batches,payment_reference','institution'=>'required|string|max:150','account_name'=>'required|string|max:150','account_number'=>'required|string|max:100','paid_at'=>'required|date|before_or_equal:today']);$batch=DB::transaction(function()use($r,$v){$payouts=Payout::with('loan.application')->whereIn('id',$v['payout_ids'])->lockForUpdate()->get();if($payouts->count()!==count($v['payout_ids'])||$payouts->contains(fn($p)=>$p->status!=='pending'))throw ValidationException::withMessages(['payout_ids'=>'One or more selected payouts are no longer pending.']);$batch=DisbursementBatch::create(['reference'=>'PAY-'.today()->format('Ymd').'-'.Str::upper(Str::random(6)),'batch_date'=>$v['paid_at'],'status'=>'paid','total_amount'=>(int)$payouts->sum('amount'),'payment_reference'=>$v['payment_reference'],'institution'=>$v['institution'],'account_name'=>$v['account_name'],'account_number'=>$v['account_number'],'paid_at'=>$v['paid_at'],'created_by'=>$r->user()->id,'paid_by'=>$r->user()->id]);foreach($payouts as $payout){$loan=$payout->loan;$serial=$loan->device_serial?:$loan->application->device_serial?:$loan->application->meter_number?:'N/A';DisbursementBatchItem::create(['disbursement_batch_id'=>$batch->id,'loan_id'=>$loan->id,'amount'=>$payout->amount,'device_serial'=>$serial]);Disbursement::firstOrCreate(['loan_id'=>$loan->id],['disbursement_batch_id'=>$batch->id,'amount'=>$payout->amount,'reference'=>$v['payment_reference'].'-'.$loan->id,'recipient'=>$loan->application->supplier?:'Supplier','confirmed_by'=>$r->user()->id,'confirmed_at'=>$v['paid_at']]);$payout->update(['status'=>'paid','disbursement_batch_id'=>$batch->id,'paid_at'=>$v['paid_at']]);$loan->update(['disbursement_status'=>'paid','disbursed_at'=>$v['paid_at']]);}$this->logAudit($r,'payouts.bulk_paid',$batch);return $batch;});return redirect('/payouts')->with('success','Bulk supplier payout '.$batch->reference.' booked for '.number_format($batch->total_amount).' TZS.');}
 public function bookPlatformCommission(Request $r,Payout $payout){$v=$r->validate(['reference'=>'required|string|max:150','booked_at'=>'required|date|before_or_equal:today']);if($payout->platform_commission_status!=='pending')throw ValidationException::withMessages(['reference'=>'This platform commission is already booked.']);$payout->update(['platform_commission_status'=>'booked','platform_commission_reference'=>$v['reference'],'platform_commission_booked_at'=>$v['booked_at']]);$this->logAudit($r,'platform_commission.booked',$payout);return back()->with('success','Platform commission booked separately.');}
 public function disbursements(Request $r){
  if($r->user()->role==='supplier'){$base=Payout::where('status','paid')->whereHas('loan.customer',fn($customer)=>$customer->where('onboarded_by',$r->user()->id));$stats=['Paid entries'=>(clone $base)->count(),'Total received'=>(clone $base)->sum('amount'),'This month'=>(clone $base)->whereBetween('paid_at',[now()->startOfMonth(),now()->endOfMonth()])->sum('amount')];$q=(clone $base)->with('loan.customer','loan.application','batch');if($r->filled('q'))$q->where(fn($x)=>$x->whereHas('loan',fn($loan)=>$loan->where('reference','like','%'.$r->q.'%')->orWhereHas('customer',fn($customer)=>$customer->where('name','like','%'.$r->q.'%')))->orWhereHas('batch',fn($batch)=>$batch->where('payment_reference','like','%'.$r->q.'%')->orWhere('reference','like','%'.$r->q.'%')));$disbursements=$q->latest('paid_at')->paginate(20)->withQueryString();return view('supplier-disbursements',compact('disbursements','stats'));}
  $eligible=Loan::with('customer','application')->where('disbursement_status','pending')->whereDoesntHave('batchItem')->latest()->get()->filter(function($loan){return ($loan->terms['category']??null)==='submeter'&&(int)$loan->payments()->where('purpose','upfront')->where('status','confirmed')->sum('amount')===(int)$loan->terms['upfront'];});
  $base=DisbursementBatch::query();$stats=['Total'=>(clone $base)->count(),'Unpaid'=>(clone $base)->where('status','unpaid')->count(),'Paid'=>(clone $base)->where('status','paid')->count(),'Total value'=>(clone $base)->sum('total_amount')];$q=DisbursementBatch::with('items.loan.customer','creator','payer');if(request()->filled('status'))$q->where('status',request('status'));$batches=$q->latest('batch_date')->latest()->paginate(20)->withQueryString();return view('disbursements',compact('eligible','batches','stats'));
 }
 public function disbursement(Request $r,DisbursementBatch $batch){$q=Payout::with('loan.customer','loan.application')->where('disbursement_batch_id',$batch->id)->where('status','paid');if($r->user()->role==='supplier')$q->whereHas('loan.customer',fn($customer)=>$customer->where('onboarded_by',$r->user()->id));$entries=$q->get();abort_if($entries->isEmpty(),404);$supplierTotal=(int)$entries->sum('amount');return view('supplier-disbursement',compact('batch','entries','supplierTotal'));}
 public function createDisbursementBatch(Request $r){$v=$r->validate(['loan_ids'=>'required|array|min:1','loan_ids.*'=>'integer|distinct|exists:loans,id','device_serials'=>'required|array']);$batch=DB::transaction(function()use($r,$v){$loans=Loan::with('application')->whereIn('id',$v['loan_ids'])->lockForUpdate()->get();if($loans->count()!==count($v['loan_ids']))throw ValidationException::withMessages(['loan_ids'=>'One or more selected loans are unavailable.']);$total=0;foreach($loans as $loan){if($loan->status!=='pending_disbursement'||($loan->terms['category']??null)!=='submeter'||$loan->batchItem)throw ValidationException::withMessages(['loan_ids'=>'A selected loan is no longer eligible.']);$paid=(int)$loan->payments()->where('purpose','upfront')->where('status','confirmed')->sum('amount');if($paid!==(int)$loan->terms['upfront'])throw ValidationException::withMessages(['loan_ids'=>'Every selected loan must have its full upfront payment confirmed.']);$serial=trim((string)($v['device_serials'][$loan->id]??$loan->application->device_serial));if($serial==='')throw ValidationException::withMessages(['device_serials'=>'A device serial is required for every selected loan.']);$total+=(int)$loan->terms['principal'];}$batch=DisbursementBatch::create(['reference'=>'DB-'.today()->format('Ymd').'-'.Str::upper(Str::random(6)),'batch_date'=>today(),'status'=>'unpaid','total_amount'=>$total,'created_by'=>$r->user()->id]);foreach($loans as $loan)DisbursementBatchItem::create(['disbursement_batch_id'=>$batch->id,'loan_id'=>$loan->id,'amount'=>$loan->terms['principal'],'device_serial'=>trim((string)($v['device_serials'][$loan->id]??$loan->application->device_serial))]);$this->logAudit($r,'disbursement_batch.created',$batch);return $batch;});return redirect('/disbursements')->with('success','Daily device batch '.$batch->reference.' created with unpaid status.');}
 public function payDisbursementBatch(Request $r,DisbursementBatch $batch,LendingService $service){$v=$r->validate(['payment_reference'=>'required|string|max:150|unique:disbursement_batches,payment_reference','institution'=>'required|string|max:150','account_name'=>'required|string|max:150','account_number'=>'required|string|max:100','paid_at'=>'required|date|before_or_equal:today']);DB::transaction(function()use($r,$v,$batch,$service){$locked=DisbursementBatch::with('items.loan.application')->lockForUpdate()->findOrFail($batch->id);if($locked->status!=='unpaid')throw ValidationException::withMessages(['payment_reference'=>'This batch has already been paid.']);foreach($locked->items as $item)$service->disburse($item->loan,$r->user(),['amount'=>$item->amount,'reference'=>$v['payment_reference'].'-'.$item->loan_id,'recipient'=>$item->loan->application->supplier?:'Device supplier','device_serial'=>$item->device_serial,'date'=>$v['paid_at'],'disbursement_batch_id'=>$locked->id]);$locked->update($v+['status'=>'paid','paid_by'=>$r->user()->id]);$this->logAudit($r,'disbursement_batch.paid',$locked);});return redirect('/disbursements')->with('success','Bulk device disbursement marked paid.');}
}
